(async () => {
  const baseJuly = "/private/var/folders/c7/vw1b0dhs3dddrx6r102srgvm0000gn/T/t5-round2-QA4J57/GPAO-T5/2026-07 정산";
  const baseAug = "/private/var/folders/c7/vw1b0dhs3dddrx6r102srgvm0000gn/T/t5-round2-QA4J57/GPAO-T5/2026-08 정산";

  async function loadCsvSummary(path) {
    const readRes = await t5.call("local_file", { action: "read", path });
    const text = readRes.text.trim();
    const lines = text.split(/\r?\n/).filter(l => l.trim().length > 0);
    if (lines.length === 0) {
      return { path, headers: [], rows: [], sums: {}, count: 0 };
    }
    const headers = lines[0].split(",").map(h => h.trim());
    const rows = lines.slice(1).map(line => line.split(",").map(c => c.trim()));
    const sums = {};
    headers.forEach((h, idx) => {
      let allNumeric = true;
      let sum = 0;
      for (const r of rows) {
        const v = r[idx].replace(/,/g, "");
        if (v === "") continue;
        const num = Number(v);
        if (Number.isNaN(num)) {
          allNumeric = false;
          break;
        }
        sum += num;
      }
      if (allNumeric) sums[h] = sum;
    });
    return { path, headers, rows, sums, count: rows.length };
  }

  const julySales = await loadCsvSummary(`${baseJuly}/2026-07 매출정산.csv`);
  const julyDetail = await loadCsvSummary(`${baseJuly}/7월 정산내역.csv`);
  const augSales = await loadCsvSummary(`${baseAug}/2026-08 매출정산.csv`);
  const augDetail = await loadCsvSummary(`${baseAug}/8월 정산내역.csv`);

  function pickMainSummary(summary1, summary2) {
    if (summary1.count !== summary2.count) {
      return summary1.count > summary2.count ? summary1 : summary2;
    }
    const sum1 = Object.values(summary1.sums).reduce((a, b) => a + b, 0);
    const sum2 = Object.values(summary2.sums).reduce((a, b) => a + b, 0);
    return sum1 >= sum2 ? summary1 : summary2;
  }

  const julyMain = pickMainSummary(julySales, julyDetail);
  const augMain = pickMainSummary(augSales, augDetail);

  function describeSummary(label, s) {
    const total = Object.entries(s.sums).map(([k, v]) => `${k}: ${v.toLocaleString()}`).join(" / ");
    return `${label} (${s.count}건) — ${total || "합계 계산 불가"}`;
  }

  // 공통으로 있는 숫자 열만 비교
  const julyNumericCols = Object.keys(julyMain.sums);
  const augNumericCols = Object.keys(augMain.sums);
  const commonCols = julyNumericCols.filter(c => augNumericCols.includes(c));

  const lines = [];
  lines.push("지난달(7월) vs 이번달(8월) 정산 요약");
  lines.push("");
  lines.push(`사용한 기준 파일`);
  lines.push(`- 7월: ${julyMain.path}`);
  lines.push(`- 8월: ${augMain.path}`);
  lines.push("");
  lines.push(describeSummary("7월 합계", julyMain));
  lines.push(describeSummary("8월 합계", augMain));
  lines.push("");
  lines.push("공통 지표 비교 (7월 → 8월)");

  if (commonCols.length === 0) {
    lines.push("- 공통 숫자 항목이 없어 직접 비교 불가");
  } else {
    for (const col of commonCols) {
      const j = julyMain.sums[col] ?? 0;
      const a = augMain.sums[col] ?? 0;
      const diff = a - j;
      const rate = j === 0 ? "-" : `${((diff / j) * 100).toFixed(1)}%`;
      const sign = diff > 0 ? "+" : "";
      lines.push(`- ${col}: 7월 ${j.toLocaleString()} → 8월 ${a.toLocaleString()} (${sign}${diff.toLocaleString()}, 변화율 ${rate})`);
    }
  }

  const summaryText = lines.join("\n");

  await t5.call("local_file", {
    action: "write",
    path: "~/Desktop/7월_vs_8월_정산_요약.txt",
    text: summaryText,
    source: baseJuly
  });

  console.log({ ok: true, summaryPath: "~/Desktop/7월_vs_8월_정산_요약.txt" });
})();

